function PageHeader({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: ReactNode }) {
  return <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="mb-2 text-[10px] font-bold uppercase tracking-[0.18em] text-[#1DB954]">{eyebrow}</p><h2 className="text-[30px] font-bold tracking-[-0.05em] text-[#f3f6f4] sm:text-[34px]">{title}</h2><p className="mt-2 max-w-2xl text-[13px] leading-6 text-[#89938d]">{description}</p></div>{action && <div className="shrink-0">{action}</div>}</div>;
}

function Modal({ open, onClose, title, subtitle, children }: { open: boolean; onClose: () => void; title: string; subtitle?: string; children: ReactNode }) {
  if (!open) return null;
  return <div className="fixed inset-0 z-50 grid place-items-center bg-black/70 p-4 backdrop-blur-sm" role="dialog" aria-modal="true" aria-label={title}><div className="max-h-[92vh] w-full max-w-[650px] overflow-y-auto rounded-[22px] border border-white/[0.12] bg-[#101614] p-5 shadow-2xl sm:p-6"><div className="mb-6 flex items-start justify-between gap-4"><div><h3 className="text-[20px] font-bold tracking-[-0.04em] text-white">{title}</h3>{subtitle && <p className="mt-1 text-[12px] leading-5 text-[#8c9790]">{subtitle}</p>}</div><button onClick={onClose} className="grid h-8 w-8 place-items-center rounded-lg text-[#a6afa9] transition hover:bg-white/[0.09] hover:text-white" aria-label="Close"><X className="h-4 w-4" /></button></div>{children}</div></div>;
}

function StatusPill({ status }: { status: string }) {
  const tones: Record<string, string> = {
    Active: "border-[#1DB954]/25 bg-[#1DB954]/12 text-[#8cf1af]", Scheduled: "border-[#d8b45a]/25 bg-[#d8b45a]/10 text-[#f4d37e]", Complete: "border-[#7eb3ff]/25 bg-[#7eb3ff]/10 text-[#a7cbff]", Draft: "border-white/[0.11] bg-white/[0.06] text-[#b3bcb7]", Expired: "border-[#f47777]/20 bg-[#f47777]/10 text-[#ffa2a2]", New: "border-[#7eb3ff]/25 bg-[#7eb3ff]/10 text-[#a7cbff]", Contacted: "border-[#d8b45a]/25 bg-[#d8b45a]/10 text-[#f4d37e]", Converted: "border-[#1DB954]/25 bg-[#1DB954]/12 text-[#8cf1af]", Lost: "border-[#f47777]/20 bg-[#f47777]/10 text-[#ffa2a2]", Imported: "border-[#1DB954]/25 bg-[#1DB954]/12 text-[#8cf1af]", Skipped: "border-[#f47777]/20 bg-[#f47777]/10 text-[#ffa2a2]",
  };
  return <span className={`inline-flex items-center gap-1.5 rounded-full border px-2 py-1 text-[10px] font-bold ${tones[status] ?? tones.Draft}`}><span className="h-1 w-1 rounded-full bg-current" />{status}</span>;
}

function Empty({ title, description }: { title: string; description: string }) {
  return <div className="grid min-h-56 place-items-center rounded-2xl border border-dashed border-white/[0.13] bg-white/[0.018] p-8 text-center"><div><div className="mx-auto grid h-10 w-10 place-items-center rounded-xl bg-[#1DB954]/10 text-[#1DB954]"><Inbox className="h-5 w-5" /></div><p className="mt-3 text-sm font-semibold text-white">{title}</p><p className="mt-1 text-xs text-[#7c8780]">{description}</p></div></div>;
}

function MetricCard({ label, value, icon: Icon, detail, positive = true }: { label: string; value: string; icon: typeof Users; detail: string; positive?: boolean }) {
  return <div className="group relative overflow-hidden rounded-2xl border border-white/[0.085] bg-[#101614] p-4 transition duration-200 hover:-translate-y-1 hover:border-[#1DB954]/28 hover:shadow-[0_18px_35px_rgba(0,0,0,.20)]"><div className="absolute -right-5 -top-5 h-24 w-24 rounded-full bg-[#1DB954]/[0.055] blur-2xl transition group-hover:bg-[#1DB954]/[0.12]" /><div className="relative flex items-start justify-between"><p className="text-[11px] font-semibold text-[#9ba59f]">{label}</p><span className="grid h-8 w-8 place-items-center rounded-lg bg-white/[0.055] text-[#85efaa]"><Icon className="h-4 w-4" /></span></div><div className="relative mt-6"><p className="text-[25px] font-bold tracking-[-0.05em] text-[#f5f8f6]">{value}</p><div className="mt-2 flex items-center gap-1.5"><span className={`inline-flex items-center gap-0.5 text-[10px] font-bold ${positive ? "text-[#7eefa6]" : "text-[#f69b9b]"}`}>{positive ? <ArrowUpRight className="h-3 w-3" /> : <ArrowDownRight className="h-3 w-3" />}Live</span><span className="text-[10px] text-[#657069]">{detail}</span></div></div></div>;
}

function downloadCsvFile(fileName: string, rows: Array<Record<string, string | number | null | undefined>>, columns: string[]) {
  const blob = new Blob([formatCsv(rows, columns)], { type: "text/csv;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = fileName;
  document.body.appendChild(link);
  link.click();
  link.remove();
  window.setTimeout(() => URL.revokeObjectURL(url), 0);
}

function dateInput(offsetDays = 0) {
  const date = new Date();
  date.setDate(date.getDate() + offsetDays);
  return date.toISOString().slice(0, 10);
}

