  const saveCustomer = (event: FormEvent) => { event.preventDefault(); if (!form.name || !form.phone || !form.industry) return toast.error("Add a name, WhatsApp number, and industry to continue."); editing ? updateCustomer(editing.id, form) : addCustomer(form); toast.success(editing ? "Customer details updated" : "Customer added to your audience"); setModalOpen(false); };
  const handleImport = (event: ChangeEvent<HTMLInputElement>) => { const file = event.target.files?.[0]; event.target.value = ""; if (!file) return; if (file.size > 1_500_000) return toast.error("Use a CSV file smaller than 1.5 MB."); const reader = new FileReader(); reader.onload = () => importCsv.mutate({ fileName: file.name, content: String(reader.result ?? ""), defaultIndustry: importIndustry.trim() || "Unspecified" }); reader.onerror = () => toast.error("The CSV could not be read. Please try again."); reader.readAsText(file); };
  const exportCustomers = () => { downloadCsvFile(csvFileName("customers"), filtered.map(customer => ({ name: customer.name, email: customer.email, phone: customer.phone, industry: customer.industry, segment: customer.segment, orders: customer.orders, lifetimeSpend: customer.spend, lastActivity: customer.lastSeen })), ["name", "email", "phone", "industry", "segment", "orders", "lifetimeSpend", "lastActivity"]); toast.success("Customer CSV downloaded."); };
